class Solution {
public:
    int movesToMakeZigzag(vector<int>& nums) {
        int n = nums.size();
        int res[2] = {0, 0};
        for (int i = 0; i < n; ++i) {
            int left = i > 0 ? nums[i - 1] : 1e9;
            int right = i < n - 1 ? nums[i + 1] : 1e9;
            int target = min(left, right) - 1;
            if (nums[i] > target) {
                res[i % 2] += nums[i] - target;
            }
        }
        return min(res[0], res[1]);
    }
};

class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        int[] res = new int[2];
        for (int i = 0; i < n; i++) {
            int left = i > 0 ? nums[i - 1] : Integer.MAX_VALUE;
            int right = i < n - 1 ? nums[i + 1] : Integer.MAX_VALUE;
            int target = Math.min(left, right) - 1;
            if (nums[i] > target) {
                res[i % 2] += nums[i] - target;
            }
        }
        return Math.min(res[0], res[1]);
    }
}

var movesToMakeZigzag = function(nums) {
    const n = nums.length;
    const res = [0, 0];
    for (let i = 0; i < n; i++) {
        const left = i > 0 ? nums[i - 1] : Infinity;
        const right = i < n - 1 ? nums[i + 1] : Infinity;
        const target = Math.min(left, right) - 1;
        if (nums[i] > target) {
            res[i % 2] += nums[i] - target;
        }
    }
    return Math.min(res[0], res[1]);
};
